import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            N = int(next(iterator))
            S = next(iterator)
            P = next(iterator)
        except StopIteration:
            break

        if S == P:
            results.append("YES")
            continue

        has_0_in_S = '0' in S
        has_1_in_S = '1' in S
        has_0_in_P = '0' in P
        has_1_in_P = '1' in P

        if (has_0_in_S and has_1_in_S) and (has_0_in_P and has_1_in_P):
            results.append("YES")
        else:
            results.append("NO")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
